1	export interface Card {
2	  monster: string;
3	  rank?: number;
4	}
5	
6	const TYPE_THRESHOLD = 3;
7	const POINTS_PER_TYPE_BEYOND_THRESHOLD = 2;
8	const BASE_POINTS = 1;
9	
10	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
11	
12	const typeOf = (card: Card): string => `${card.monster}-${card.rank}`;
13	
14	const countDistinctTypes = (army: Card[]): number =>
15	  new Set(army.map(typeOf)).size;
16	
17	const pointsForEachSphinx = (distinctTypes: number): number => {
18	  const typesBeyondThreshold = distinctTypes - TYPE_THRESHOLD;
19	  return typesBeyondThreshold > 0
20	    ? POINTS_PER_TYPE_BEYOND_THRESHOLD * typesBeyondThreshold
21	    : BASE_POINTS;
22	};
23	
24	export const scoreArmy = (army: Card[]): number =>
25	  army.filter(isSphinx).length *
26	  pointsForEachSphinx(countDistinctTypes(army));
