const ranksByMonster = (army: Card[]): Map<string, Set<number | undefined>> =>
  army.reduce((ranks, card) => {
    const ranksOfMonster = ranks.get(card.monster) ?? new Set();
    return ranks.set(card.monster, ranksOfMonster.add(card.rank));
  }, new Map<string, Set<number | undefined>>());

const countDistinctTypes = (army: Card[]): number =>
  [...ranksByMonster(army).values()].reduce(
    (total, ranks) => total + ranks.size,
    0,
  );

